<?php declare(strict_types=1);
namespace Modules\PromptEngine\Services;
use RuntimeException;
final class PromptQualityControlService { public static function negativeConstraints(): array { return ['malformed Chinese characters','incorrect glyph structure','random pseudo-Chinese text','gibberish typography','misspelled pinyin','distorted calligraphy','duplicated objects','deformed hands','cropped main character','cluttered layout','poor hierarchy','illegible microtext','irrelevant cultural props','modern objects','plastic-looking materials','neon colors','watermark','logo','QR code','UI interface','low resolution','oversaturation']; } public function inspect(array $result): array { $prompt=$result['image_prompt']['prompt']??''; $errors=[]; if(preg_match('/\{\{[^}]+\}\}/',$prompt))$errors[]='unresolved_placeholders'; if(!str_contains($prompt,$result['analysis']['character']))$errors[]='character_not_preserved'; if($prompt==='')$errors[]='empty_prompt'; if($errors)throw new RuntimeException('Prompt quality control failed: '.implode(', ',$errors)); return ['passed'=>true,'checks'=>['character_accuracy','visual_relevance','placeholder_resolution','platform_syntax']]; } }
